// This file was generated by Prisma, and assumes you run Prisma commands using `bun --bun run prisma [command]`.
import { defineConfig, env } from '@prisma/config';
import 'dotenv/config';
import { resolveDatabaseUrl } from './src/config/database-url';

// Resolved through the same helper the application uses. Without this, the app
// could talk to the test branch while `prisma migrate deploy` migrated the
// developer database, because this CLI never loads `src/config` and would read
// DATABASE_URL straight out of `.env`.
const databaseUrl = resolveDatabaseUrl({
  DATABASE_URL: env('DATABASE_URL'),
  TEST_DATABASE_URL: process.env.TEST_DATABASE_URL,
});

export default defineConfig({
  schema: 'prisma/schema',
  migrations: {
    path: 'prisma/migrations',
    seed: 'bun run ./prisma/seed.ts',
  },
  datasource: {
    url: databaseUrl,
  },
});
